#include <Eigen/Dense>
#include <iostream>
#include <cmath>
#include <iomanip>

using namespace Eigen;

// CST triangle membrane stiffness (3x3 per node -> 6x6)
Matrix<double,6,6> cstStiffness(const MatrixXd& coords, double E, double nu, double t) {
    // coords: 3x2 (x,y) for the 3 nodes
    double x1=coords(0,0), y1=coords(0,1);
    double x2=coords(1,0), y2=coords(1,1);
    double x3=coords(2,0), y3=coords(2,1);
    double A = 0.5*((x2-x1)*(y3-y1)-(x3-x1)*(y2-y1));
    // B matrix 3x6
    Matrix<double,3,6> B;
    B.setZero();
    double b1=y2-y3, b2=y3-y1, b3=y1-y2;
    double c1=x3-x2, c2=x1-x3, c3=x2-x1;
    B(0,0)=b1; B(0,2)=b2; B(0,4)=b3;
    B(1,1)=c1; B(1,3)=c2; B(1,5)=c3;
    B(2,0)=c1; B(2,1)=b1; B(2,2)=c2; B(2,3)=b2; B(2,4)=c3; B(2,5)=b3;
    B /= (2.0*A);
    Matrix3d D;
    double f = E/(1.0-nu*nu);
    D << f, f*nu, 0,
         f*nu, f, 0,
         0, 0, f*(1.0-nu)/2.0;
    Matrix<double,6,6> K = t*std::abs(A)*B.transpose()*D*B;
    return K;
}

