    // KSUM: 4 blocks of 3x3 (per node, 2 DOF -> but 3x3? Actually per node 2 DOF)
    // We'll accumulate into 8x8 directly
    Matrix<double,8,8> K = Matrix<double,8,8>::Zero();
    for(int j=0;j<4;j++){
        int n0=M[3*j]-1, n1=M[3*j+1]-1, n2=M[3*j+2]-1;
        MatrixXd c(3,2);
        c.row(0)=nodes.row(n0);
        c.row(1)=nodes.row(n1);
        c.row(2)=nodes.row(n2);
        Matrix<double,6,6> kt = cstStiffness(c,E,nu,t);
        int idx[3]={n0,n1,n2};
        for(int a=0;a<3;a++)for(int b=0;b<3;b++){
            for(int i=0;i<2;i++)for(int jj=0;jj<2;jj++){
                K(2*idx[a]+i, 2*idx[b]+jj) += kt(2*a+i, 2*b+jj);
            }
        }
    }
    // print JSON
    std::cout << "{\"stiffness_matrix\":[";
    for(int i=0;i<8;i++){
        std::cout << "[";
        for(int j=0;j<8;j++){
            std::cout << std::scientific << std::setprecision(6) << K(i,j);
            if(j<7) std::cout << ",";
        }
        std::cout << "]";
        if(i<7) std::cout << ",";
    }
    std::cout << "]}" << std::endl;
    return 0;
}
